test("flags two claims as one group when the four fields match and claim ids differ", function () {
  var claims = [
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.equal(result.groups.length, 1);
  assert.deepEqual(result.groups[0].claimIds.slice().sort(), ["C-1", "C-2"]);
  assert.equal(result.groups[0].patientRef, "P-001");
  assert.equal(result.groups[0].serviceDate, "2024-03-05");
  assert.equal(result.groups[0].procedureCode, "99213");
  assert.equal(result.groups[0].amount, 120.00);
});

test("does not flag claims when only the amount differs", function () {
  var claims = [
    { claimId: "C-3", patientRef: "P-002", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-4", patientRef: "P-002", serviceDate: "2024-03-05", procedureCode: "99213", amount: 125.00 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.deepEqual(result, { groups: [] });
});

test("puts three matching claims in one group instead of three pairs", function () {
  var claims = [
    { claimId: "C-5", patientRef: "P-003", serviceDate: "2024-03-06", procedureCode: "99214", amount: 80.00 },
    { claimId: "C-6", patientRef: "P-003", serviceDate: "2024-03-06", procedureCode: "99214", amount: 80.00 },
    { claimId: "C-7", patientRef: "P-003", serviceDate: "2024-03-06", procedureCode: "99214", amount: 80.00 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.equal(result.groups.length, 1);
  assert.equal(result.groups[0].claimIds.length, 3);
  assert.deepEqual(result.groups[0].claimIds.slice().sort(), ["C-5", "C-6", "C-7"]);
  assert.equal(result.groups[0].patientRef, "P-003");
  assert.equal(result.groups[0].serviceDate, "2024-03-06");
  assert.equal(result.groups[0].procedureCode, "99214");
  assert.equal(result.groups[0].amount, 80.00);
});

test("does not flag identical claims passed in different batches", function () {
  var batchA = [
    { claimId: "C-8", patientRef: "P-004", serviceDate: "2024-03-07", procedureCode: "99213", amount: 120.00 }
  ];
  var batchB = [
    { claimId: "C-9", patientRef: "P-004", serviceDate: "2024-03-07", procedureCode: "99213", amount: 120.00 }
  ];
  var resultA = code.findDuplicateGroups(batchA);
  var resultB = code.findDuplicateGroups(batchB);
  assert.deepEqual(resultA, { groups: [] });
  assert.deepEqual(resultB, { groups: [] });
});

test("shows claim ids and the four matched values for each duplicate group", function () {
  var claims = [
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.equal(result.groups.length, 1);
  var group = result.groups[0];
  assert.deepEqual(group.claimIds.slice().sort(), ["C-1", "C-2"]);
  assert.equal(group.patientRef, "P-001");
  assert.equal(group.serviceDate, "2024-03-05");
  assert.equal(group.procedureCode, "99213");
  assert.equal(group.amount, 120.00);
});

test("leaves the review list empty when no claims form a group", function () {
  var claims = [
    { claimId: "C-3", patientRef: "P-002", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-4", patientRef: "P-002", serviceDate: "2024-03-05", procedureCode: "99213", amount: 125.00 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.deepEqual(result, { groups: [] });
});

test("does not delete edit or reject claims that match exactly", function () {
  var claims = [
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 }
  ];
  var snapshot = [
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.deepEqual(claims, snapshot);
  assert.equal(claims.length, 2);
  assert.equal(result.groups.length, 1);
  assert.deepEqual(result.groups[0].claimIds.slice().sort(), ["C-1", "C-2"]);
});

test("does not flag near matches when the service date is one day apart or the amount is a few cents apart", function () {
  var datePair = [
    { claimId: "C-10", patientRef: "P-005", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-11", patientRef: "P-005", serviceDate: "2024-03-06", procedureCode: "99213", amount: 120.00 }
  ];
  var amountPair = [
    { claimId: "C-12", patientRef: "P-006", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-13", patientRef: "P-006", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.03 }
  ];
  var dateResult = code.findDuplicateGroups(datePair);
  var amountResult = code.findDuplicateGroups(amountPair);
  assert.deepEqual(dateResult, { groups: [] });
  assert.deepEqual(amountResult, { groups: [] });
});
